def append_to_file():
    with open('scripts/generators/gen_esportes_extra.py', 'r', encoding='utf-8') as f:
        content = f.read()

    # check if EXTRA_ESPORTES has the closing bracket
    # replace closing bracket with EXTRA_RADICAIS + EXTRA_PRECISAO
    rad_code = ""
    for item in EXTRA_RADICAIS:
        rad_code += f"    {repr(item)},\n"
    prec_code = ""
    for item in EXTRA_PRECISAO:
        prec_code += f"    {repr(item)},\n"

    # In gen_esportes_extra.py:
    target = '    ("Bokator Cambojano", "lutas", ["ArteMarcialMaisAntigaDosTemplos", "GravadaNosMurosDeAngkorWat", "LençosColoridosKramaAmarrados", "LutaComJoelhosECotovelo"], ["Uma das mais antigas artes marciais do sudeste asiático gravada nos relevos de templos milenares de pedra", "Os guerreiros amarram lenços tradicionais xadrez na cintura e na cabeça nos combates", "Possui milhares de técnicas baseadas em animais míticos como o garuda, o macaco e o leão", "Reconhecido recentemente pela UNESCO como Patrimônio Imaterial da Humanidade"])\n]'
    
    replacement = '    ("Bokator Cambojano", "lutas", ["ArteMarcialMaisAntigaDosTemplos", "GravadaNosMurosDeAngkorWat", "LençosColoridosKramaAmarrados", "LutaComJoelhosECotovelo"], ["Uma das mais antigas artes marciais do sudeste asiático gravada nos relevos de templos milenares de pedra", "Os guerreiros amarram lenços tradicionais xadrez na cintura e na cabeça nos combates", "Possui milhares de técnicas baseadas em animais míticos como o garuda, o macaco e o leão", "Reconhecido recentemente pela UNESCO como Patrimônio Imaterial da Humanidade"]),\n\n    # --- radicais (56 itens) ---\n' + rad_code + '\n    # --- precisao (56 itens) ---\n' + prec_code + ']'
    
    if target in content:
        new_content = content.replace(target, replacement)
        with open('scripts/generators/gen_esportes_extra.py', 'w', encoding='utf-8') as f:
            f.write(new_content)
        print("Updated gen_esportes_extra.py successfully!")
    else:
        print("Target not found! Checking tail...")
        print(content[-300:])

if __name__ == '__main__':
    append_to_file()
